package main
import "fmt"
import "bufio"
import "os"
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    texto := scanner.Text()

    scanner.Scan()
    substring := scanner.Text()
    cont := 0

    for i := 0; i <= len(texto)-len(substring); i++ {
        if texto[i:i+len(substring)] == substring {
            cont++
        }
    }

    fmt.Println(cont)
}
